const stores = client.beta.memoryStores;
const prior = await stores.memoryVersions.retrieve(versionId, {
  memory_store_id: storeId
});
if (prior.content == null) {
  throw new Error("Version content unavailable");
}
const current = await stores.memories.retrieve(memoryId, {
  memory_store_id: storeId
});
await stores.memories.update(memoryId, {
  memory_store_id: storeId,
  content: prior.content,
  precondition: {
    type: "content_sha256",
    content_sha256: current.content_sha256
  }
});
